#!/usr/bin/env bash
# Question 4: ${Q4_APP} cannot list Pods. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q4_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q4_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q4_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: v1
kind: ServiceAccount
metadata:
  name: ${Q4_APP}-sa
  namespace: ${Q4_NS}
---
apiVersion: rbac.authorization.k8s.io/v1
kind: Role
metadata:
  name: ${Q4_APP}-reader
  namespace: ${Q4_NS}
rules:
  - apiGroups: [""]
    resources: ["pods"]
    verbs: ["get", "list"]
---
apiVersion: rbac.authorization.k8s.io/v1
kind: RoleBinding
metadata:
  name: ${Q4_APP}-reader
  namespace: ${Q4_NS}
roleRef:
  apiGroup: rbac.authorization.k8s.io
  kind: Role
  name: ${Q4_APP}-reader
subjects:
  - kind: ServiceAccount
    name: ${Q4_APP}-sa
    namespace: ${Q4_NS}
---
apiVersion: apps/v1
kind: Deployment
metadata:
  name: ${Q4_APP}
  namespace: ${Q4_NS}
spec:
  replicas: 0
  selector:
    matchLabels: { app: ${Q4_APP} }
  template:
    metadata:
      labels: { app: ${Q4_APP} }
    spec:
      serviceAccountName: ${Q4_APP}-sa
      containers:
        - name: reporter
          image: alpine:3.21
          env:
            - name: NS
              valueFrom: { fieldRef: { fieldPath: metadata.namespace } }
          command:
            - sh
            - -c
            - |
              D=/var/run/secrets/kubernetes.io/serviceaccount
              while true; do
                if [ ! -r \$D/token ]; then
                  echo "no token at \$D/token"
                elif out=\$(wget -q -O /dev/null --no-check-certificate --header "Authorization: Bearer \$(cat \$D/token)" https://kubernetes.default.svc/api/v1/namespaces/\$NS/pods 2>&1); then
                  echo 200
                else
                  echo "\$out"
                fi
                sleep 5
              done
EOF

case "${Q4_FAULT}" in
  role-verb)
    kubectl -n "${Q4_NS}" patch role "${Q4_APP}-reader" --type=json -p '[{"op":"replace","path":"/rules/0/verbs","value":["get"]}]'
    ;;
  role-resource)
    kubectl -n "${Q4_NS}" patch role "${Q4_APP}-reader" --type=json -p '[{"op":"replace","path":"/rules/0/resources","value":["pod"]}]'
    ;;
  role-api-group)
    kubectl -n "${Q4_NS}" patch role "${Q4_APP}-reader" --type=json -p '[{"op":"replace","path":"/rules/0/apiGroups","value":["apps"]}]'
    ;;
  binding-subject-ns)
    kubectl -n "${Q4_NS}" patch rolebinding "${Q4_APP}-reader" --type=json -p '[{"op":"replace","path":"/subjects/0/namespace","value":"default"}]'
    ;;
  binding-role-ref)
    kubectl -n "${Q4_NS}" delete rolebinding "${Q4_APP}-reader"
    kubectl -n "${Q4_NS}" create rolebinding "${Q4_APP}-reader" --role="${Q4_APP}-viewer" --serviceaccount="${Q4_NS}:${Q4_APP}-sa"
    ;;
  binding-subject-user)
    kubectl -n "${Q4_NS}" patch rolebinding "${Q4_APP}-reader" --type=json -p '[{"op":"replace","path":"/subjects/0","value":{"kind":"User","apiGroup":"rbac.authorization.k8s.io","name":"'"${Q4_APP}"'-sa"}}]'
    ;;
  wrong-sa)
    kubectl -n "${Q4_NS}" set serviceaccount "deployment/${Q4_APP}" default
    ;;
  automount-off)
    kubectl -n "${Q4_NS}" patch serviceaccount "${Q4_APP}-sa" -p '{"automountServiceAccountToken":false}'
    ;;
  pod-automount-off)
    kubectl -n "${Q4_NS}" patch deployment "${Q4_APP}" --type=json -p '[{"op":"add","path":"/spec/template/spec/automountServiceAccountToken","value":false}]'
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac

kubectl -n "${Q4_NS}" scale "deployment/${Q4_APP}" --replicas=1
kubectl -n "${Q4_NS}" rollout status "deployment/${Q4_APP}" --timeout=240s
for _ in $(seq 1 30); do
  line="$(kubectl -n "${Q4_NS}" logs "deployment/${Q4_APP}" --tail=1 2>/dev/null)"
  [[ -n "$line" && "$line" != 200 ]] && break
  sleep 2
done
[[ "$(kubectl -n "${Q4_NS}" logs "deployment/${Q4_APP}" --tail=1 2>/dev/null)" != 200 ]] || { echo "${Q4_APP} still lists Pods" >&2; exit 1; }
